('37c08243-cda7-53d6-84a6-bb86704a8aff', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan hevok ji bo fêmkirina têkiliya ziman û nasnameyê herî guncaw e?', 'Ziman dikare hafiza, çand û nasnameya civakê hilgire', 'Ziman tenê ji bo hesabkirinê ye', 'Ziman bi çandê re têkiliya nîne', 'Hemû ziman di hemû cihan de yek in', 'A', 'Ziman tenê amûra ragihandinê nîne; ew çîrok, bîranîn û awayê dîtina civakê jî hildigire.', 'Ziman tenê amûra ragihandinê nîne; ew çîrok, bîranîn û awayê dîtina civakê jî hildigire.', 'Dil yalnızca bir iletişim aracı değildir; hikâyeyi, hafızayı ve toplumun bakış biçimini de taşır.', 3, true, 'multiple_choice', NULL, NULL, 'Jineolojî movement media + supporting academic context', 'https://anfenglishmobile.com/features/twitterkurds-takes-the-civil-disobedience-campaign-online-3254; https://kongra-star.org/eng/wp-content/uploads/2025/01/Annual-Newsletter-of-the-Womens-Revolution.pdf; Cambridge, Beyond Feminism? Jineolojî and the Kurdish Women’s Freedom Movement', 'approved', 'Kurmancî', 1, now()), -- yerel: curated_movement_0013
('fefd1bc5-65ec-5920-9513-a9b139cbab76', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Alfabeya Kurdî ya latînî ji çend tîpan pêk tê?', '29', '31', '26', '34', 'B', 'Alfabeya kurdî ya latînî 31 tîpan dihewîne: 8 dengdêr û 23 dengdar.', 'Alfabeya kurdî ya latînî 31 tîpan dihewîne: 8 dengdêr û 23 dengdar.', 'Kürtçe Latin alfabesi 31 harften oluşur: 8 sesli, 23 sessiz.', 1, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0001
('12830f3b-fad9-55d5-a202-b32c05f465b5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Alfabeya latînî ya Kurmancî ji aliyê kê ve hat sîstematîzekirin?', 'Ehmedê Xanî', 'Celadet Alî Bedirxan', 'Melayê Cizîrî', 'Şerefxanê Bidlîsî', 'B', 'Celadet Alî Bedirxan alfabeya latînî ya Kurmancî rêk xist û di kovara Hawarê de belav kir. Bi vê yekê nivîsa Kurmancî ya latînî bû bingeha nivîsandina nûjen.', 'Celadet Alî Bedirxan alfabeya latînî ya Kurmancî rêk xist û di kovara Hawarê de belav kir. Bi vê yekê nivîsa Kurmancî ya latînî bû bingeha nivîsandina nûjen.', 'Celadet Alî Bedirxan, Kurmancî Latin alfabesini düzenleyip Hawar dergisinde yaygınlaştırdı. Böylece Latin harfli Kürtçe yazı modern yazının temeli oldu.', 2, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0002
('2b5b3057-0fc4-52af-9de7-cd6d5f728437', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di alfabeya kurdî ya latînî de çend dengdêr (vowel) hene?', '8', '5', '6', '10', 'A', 'Dengdêrên kurdî ev in: a, e, ê, i, î, o, u, û.', 'Dengdêrên kurdî ev in: a, e, ê, i, î, o, u, û.', 'Kürtçedeki sesliler şunlardır: a, e, ê, i, î, o, u, û.', 1, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0003
('fc102bc1-060f-5c7e-bc3b-3708d864ee0a', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de girêdana navdêrê bi rengdêrekê an bi navdêreke din re bi çi tê çêkirin?', 'Daçek', 'Cînav', 'Veqetandek (izafe)', 'Bêjeya pirsê', 'C', 'Di Kurmancî de navdêr bi veqetandekê (îzafeyê) bi rengdêr an navdêreke din ve tê girêdan: kitêba min, mala mezin. Daçek û cînav vê girêdanê çênakin.', 'Di Kurmancî de navdêr bi veqetandekê (îzafeyê) bi rengdêr an navdêreke din ve tê girêdan: kitêba min, mala mezin. Daçek û cînav vê girêdanê çênakin.', 'Kurmancîde isim, izafe (veqetandek) ile sıfata ya da başka bir isme bağlanır: kitêba min, mala mezin. Edat ve zamir bu bağı kurmaz.', 3, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0004
('5fb2e4a0-c08f-52bf-ae9a-8d2a783a6615', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de peyva "jin" ji kîjan zayendê ye?', 'Nêr', 'Mê', 'Bêzayend', 'Herdu jî', 'B', 'Di Kurmancî de her navdêr zayendek digire; "jin" mê ye, loma veqetandeka wê "-a" ye: "jina baş".', 'Di Kurmancî de her navdêr zayendek digire; "jin" mê ye, loma veqetandeka wê "-a" ye: "jina baş".', 'Kurmancîde her isim bir cinsiyet alır; "jin" dişildir, bu yüzden izafesi "-a" olur: "jina baş".', 3, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0005
('8600cd83-25fd-5d3b-bd2b-04263beedf0d', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Nîşana pirjimariyê ya rewşa tewandî (oblique) di Kurmancî de kîjan e?', '-an', '-ek', '-ê', '-ne', 'A', 'Di rewşa tewandî de navdêrên pirjimar "-an" digirin: "Ez pirtûk-an dixwînim".', 'Di rewşa tewandî de navdêrên pirjimar "-an" digirin: "Ez pirtûk-an dixwînim".', 'Bükünlü (oblique) durumda çoğul isimler "-an" alır: "Ez pirtûkan dixwînim".', 3, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0006
('c5f11f76-3de7-5ffa-8701-43e952885970', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Lêkera "kirin" di dema niha de ji bo kesê sêyemîn ê yekjimar çawa tê kişandin?', 'Ew kir', 'Ew bike', 'Ew dike', 'Ew kiriye', 'C', 'Dema niha bi pêşgira "di-" tê çêkirin: di- + k(ir) + -e = dike.', 'Dema niha bi pêşgira "di-" tê çêkirin: di- + k(ir) + -e = dike.', 'Şimdiki zaman "di-" ön ekiyle kurulur: di- + k(ir) + -e = dike.', 2, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0007
('3d1122b3-52c2-5f22-9329-0083e296d709', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "ergatîf" çi tê wateyê?', 'Di dema niha de lêker bi biker re hevaheng dibe', 'Di dema borî ya lêkerên gerguhêz de bikerê tewandî', 'Navdêr li gorî zayendê tê dabeşkirin', 'Di lêkerên negerguhêz de biker her tim tewandî ye', 'B', 'Ergatîf: di dema borî de bi lêkerên gerguhêz re biker tê tewandin û lêker li gorî bireserê tê kişandin — "Min pirtûk xwend".', 'Ergatîf: di dema borî de bi lêkerên gerguhêz re biker tê tewandin û lêker li gorî bireserê tê kişandin — "Min pirtûk xwend".', 'Ergatif: geçmiş zamanda geçişli fiillerde özne büküme girer ve fiil nesneye göre çekimlenir — "Min pirtûk xwend".', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0008
('27547036-7ab8-59c6-b456-26768eac41dd', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "rojname" ji kîjan du peyvan pêk tê?', 'Roj + name', 'Ro + jname', 'Rojan + me', 'Roja + nem', 'A', '"Roj" (roj/tav) û "name" (nivîs) tên cem hev: nivîsa rojane.', '"Roj" (roj/tav) û "name" (nivîs) tên cem hev: nivîsa rojane.', '"Roj" (gün) ve "name" (yazı) birleşir: günlük yazı, yani gazete.', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0009
('62816527-f0b1-5b7a-8c74-f1953d7ca558', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "hesp" bi Tirkî çi ye?', 'köpek', 'at', 'kuş', 'koyun', 'B', '"Hesp" bi Tirkî "at" e; heywanekî çarling ê siwarbûnê ye. Mînak: "Hesp direve."', '"Hesp" bi Tirkî "at" e; heywanekî çarling ê siwarbûnê ye. Mînak: "Hesp direve."', '"Hesp" Türkçede "at" demektir; binilen dört ayaklı bir hayvandır. Örnek: "Hesp direve." (At koşuyor.)', 1, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0011
('b0d15aad-f699-55e1-aef9-d3f10baa1826', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hevwateya peyva "dilgeş" di Kurmancî de kîjan e?', 'Xemgîn', 'Şa', 'Westiyayî', 'Tirsonek', 'B', '"Dilgeş" û "şa" herdu jî kêfxweşiyê nîşan didin.', '"Dilgeş" û "şa" herdu jî kêfxweşiyê nîşan didin.', '"Dilgeş" ve "şa" ikisi de neşeli/sevinçli anlamına gelir.', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0013
('7939dc08-2006-5244-88b2-4d372b66a482', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Dijwateya peyva "germ" di Kurmancî de kîjan e?', 'Sar', 'Nerm', 'Tarî', 'Giran', 'A', '"Germ" û "sar" dijwate ne.', '"Germ" û "sar" dijwate ne.', '"Germ" (sıcak) ile "sar" (soğuk) zıt anlamlıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0014
('34b37f94-781f-510f-bb60-5df823f2c448', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "daçek" (preposition/postposition) çi ye?', 'avahiya lêkerê ya ku kiryarek berî kiryareke din a rabirdûyê qediyaye nîşan dide', 'Peyvên wek "di, bi, ji, li" yên ku têkiliya navdêran diyar dikin', '"Tu" yekjimar, "hûn" pirjimar/rêzdarî ye', 'guhertina paşgira navdêr an cînavkan li gorî rola wan a di hevokê de', 'B', 'Daçek têkiliya di navbera navdêr û beşên din ên hevokê de diyar dike: "li malê", "bi destan".', 'Daçek têkiliya di navbera navdêr û beşên din ên hevokê de diyar dike: "li malê", "bi destan".', 'Edatlar isimle cümlenin diğer öğeleri arasındaki ilişkiyi belirtir: "li malê", "bi destan".', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0015
('91a8aa2f-42c8-5267-919f-85a1c107010e', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "raweya fermanî" ya lêkera "hatin" ji bo kesê duyemîn ê yekjimar kîjan e?', 'Were', 'Hat', 'Tê', 'Hatiye', 'A', 'Raweya fermanî ya "hatin" bi awayê "were" (tu) û "werin" (hûn) tê bikaranîn.', 'Raweya fermanî ya "hatin" bi awayê "were" (tu) û "werin" (hûn) tê bikaranîn.', '"Hatin" fiilinin emir kipi "were" (sen) ve "werin" (siz) şeklindedir.', 5, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0016
('a8008962-2c1b-5c8d-88cc-29746b68e25c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Rast e an şaş e: Di Kurmancî de tîpa "Q" heye.', 'Rast', 'Şaş', '-', '-', 'A', 'Erê, tîpa "q" di alfabeya kurdî de heye: "qelem", "qij".', 'Erê, tîpa "q" di alfabeya kurdî de heye: "qelem", "qij".', 'Evet, Kürtçe alfabede "q" harfi vardır: "qelem", "qij".', 2, true, 'true_false', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0017
('35d6e71b-ca12-59a4-b378-fa71da37c752', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kovara "Hawar" bi taybetî ji bo çi girîng e?', 'Belavkirina alfabeya latînî ya kurdî', 'Weşandina romana yekem a kurdî', 'Amadekirina ferhenga mezin a kurdî', 'Tomarkirina stranên dengbêjên Serhedê', 'A', 'Hawar di 1932an de li Şamê dest pê kir û alfabeya kurdî ya latînî belav kir. Bi xebatên xwe yên zimanî ew bû dibistana Kurmanciya nûjen.', 'Hawar di 1932an de li Şamê dest pê kir û alfabeya kurdî ya latînî belav kir. Bi xebatên xwe yên zimanî ew bû dibistana Kurmanciya nûjen.', 'Hawar 1932''de Şam''da çıkmaya başladı ve Kürtçe Latin alfabesini yaygınlaştırdı. Dil çalışmalarıyla modern Kurmancînin okulu oldu.', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0019
('3b8d976f-f9a1-58f8-8f77-f7f9901c2699', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de cudahiya "min" û "ez" çi ye?', 'Herdu jî heman in', '"Ez" rewşa xwerû, "min" rewşa tewandî ye', '"Min" pirjimar e', '"Ez" tenê di dema borî de tê bikaranîn', 'B', '"Ez diçim" (xwerû) lê "Min got" (tewandî) — rewş li gorî dem û gerguhêziya lêkerê diguhere.', '"Ez diçim" (xwerû) lê "Min got" (tewandî) — rewş li gorî dem û gerguhêziya lêkerê diguhere.', '"Ez diçim" (yalın) ama "Min got" (bükünlü) — durum, fiilin zamanına ve geçişliliğine göre değişir.', 5, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0020
('2c499fe1-6f35-5e96-af78-da5799ef9050', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "dar" bi Tirkî çi ye?', 'taş', 'yol', 'kapı', 'ağaç', 'D', '"Dar" bi Tirkî "ağaç" e; riwekeke bilind a bi qurm û pelan e. Mînak: "Dar şîn bû."', '"Dar" bi Tirkî "ağaç" e; riwekeke bilind a bi qurm û pelan e. Mînak: "Dar şîn bû."', '"Dar" Türkçede "ağaç" demektir; gövdeli ve yapraklı yüksek bir bitkidir. Örnek: "Dar şîn bû." (Ağaç yeşerdi.)', 1, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0021
('7f169edd-96e7-5817-bb60-fd2ef12fb75f', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hejmara "deh" di Kurmancî de bi hejmarî çi ye?', '7', '12', '20', '10', 'D', 'Hejmarên bingehîn: yek, du, sê, çar, pênc, şeş, heft, heşt, neh, deh.', 'Hejmarên bingehîn: yek, du, sê, çar, pênc, şeş, heft, heşt, neh, deh.', 'Temel sayılar: yek, du, sê, çar, pênc, şeş, heft, heşt, neh, deh (10).', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0024
('98a9a672-c24e-5082-a1d5-505ca0149089', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "-ek" wek paşgir çi diyar dike?', 'nebinavkirîbûn (yek/bir)', 'cînavkên kesane', 'kesê ku karekî dike', 'lêkera gerguhêz', 'A', '"Pirtûkek" wateya "bir kitap" dide; ew nîşana nebinavkirîbûnê ye.', '"Pirtûkek" wateya "bir kitap" dide; ew nîşana nebinavkirîbûnê ye.', '"Pirtûkek" bir kitap demektir; belirsizlik ekidir.', 3, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0025
('8be2d78f-940b-5767-8b5b-1040090a951c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hevoka "Min ew dît" de lêker li gorî kê tê kişandin?', 'Li gorî bireserê (ew)', 'Li gorî bikerê (min)', 'Li gorî demê', 'Li gorî zayendê', 'A', 'Di dema borî ya lêkerên gerguhêz de lêker li gorî bireserê tê kişandin — ev taybetiya ergatîfê ye.', 'Di dema borî ya lêkerên gerguhêz de lêker li gorî bireserê tê kişandin — ev taybetiya ergatîfê ye.', 'Geçmiş zamanda geçişli fiil nesneye göre çekimlenir — bu ergatifliğin özelliğidir.', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0027
('35f190aa-4fe2-5ffc-bca3-05ee5e929fab', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "xwendegeh" ji kîjan koka lêkerê tê?', 'Gotin', 'Xwendin', 'Xwarin', 'Nivîsîn', 'B', '"Xwendegeh" ji koka "xwendin" û paşgira cih "-geh" pêk tê: cihê xwendinê.', '"Xwendegeh" ji koka "xwendin" û paşgira cih "-geh" pêk tê: cihê xwendinê.', '"Xwendegeh" (okul), "xwendin" (okumak) kökü ve yer eki "-geh"ten oluşur.', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0028
('7f9ae733-aacd-534a-9053-b964a48e1e31', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Paşgira "-istan/-stan" di peyvên wek "Kurdistan" de çi diyar dike?', 'Kesayet', 'Dem', 'Hejmar', 'Cih / war', 'D', '"-stan" paşgira cih e: warê kurdan.', '"-stan" paşgira cih e: warê kurdan.', '"-stan" yer ekidir: Kürtlerin yurdu.', 3, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0029
('ac4d652e-e795-57e2-b76f-d6d754c74287', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de cudahiya "tu" û "hûn" çi ye?', '"Tu" yekjimar, "hûn" pirjimar/rêzdarî ye', 'Herdu jî pirjimar in', '"Tu" tenê ji bo jinan e', '"Hûn" tenê di nivîsê de tê bikaranîn', 'A', '"Tu" ji bo yek kesî, "hûn" ji bo gelek kesan an ji bo rêzgirtinê tê bikaranîn.', '"Tu" ji bo yek kesî, "hûn" ji bo gelek kesan an ji bo rêzgirtinê tê bikaranîn.', '"Tu" tekil, "hûn" çoğul ya da saygı ifadesidir.', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0030
('89979f9b-0c27-5e5e-8576-89d9b9b3f0ed', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "raweya bilanî" (subjunctive) bi kîjan pêşgirê tê çêkirin?', 'di-', 'na-', 'bi-', 'ne-', 'C', 'Raweya bilanî bi "bi-" tê çêkirin: "ez biçim" (gideyim).', 'Raweya bilanî bi "bi-" tê çêkirin: "ez biçim" (gideyim).', 'İstek kipi "bi-" ile kurulur: "ez biçim" (gideyim).', 5, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0031
('43744cbc-5886-5324-9e87-d722c992808c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Nîşana neyîniyê ya dema niha di kurmancî de kîjan e?', 'ne-', 'na-', 'bi-', 'di-', 'B', 'Dema niha bi "na-" neyînî dibe: "ez naçim" (gitmiyorum).', 'Dema niha bi "na-" neyînî dibe: "ez naçim" (gitmiyorum).', 'Şimdiki zaman "na-" ile olumsuzlanır: "ez naçim" (gitmiyorum).', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0032
('4a91f22d-dfe1-5b23-a489-22bd8bfa6182', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Rast e an şaş e: Di kurmancî de navdêr xwedî zayend in (nêr û mê).', 'Rast', 'Şaş', '-', '-', 'A', 'Erê, her navdêreke kurmancî nêr an mê ye û ev yek veqetandekê diyar dike.', 'Erê, her navdêreke kurmancî nêr an mê ye û ev yek veqetandekê diyar dike.', 'Evet, Kurmancîde her isim eril ya da dişildir ve bu izafeyi belirler.', 2, true, 'true_false', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0033
('8b491960-6386-530c-8ad6-4189b2cf2915', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "dest" bi Tirkî çi ye?', 'el', 'ayak', 'baş', 'sırt', 'A', '"Dest" bi Tirkî "el" e; endamê ku em pê digirin û dinivîsin e. Mînak: "Destê xwe bişo."', '"Dest" bi Tirkî "el" e; endamê ku em pê digirin û dinivîsin e. Mînak: "Destê xwe bişo."', '"Dest" Türkçede "el" demektir; tutup yazdığımız organdır. Örnek: "Destê xwe bişo." (Elini yıka.)', 1, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0036
('ae1159e0-19ba-537c-8b80-b67945676a6d', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Dijwateya peyva "dirêj" di Kurmancî de kîjan e?', 'Kurt', 'Fireh', 'Giran', 'Nerm', 'A', '"Dirêj" (uzun) û "kurt" (kısa) dijwate ne.', '"Dirêj" (uzun) û "kurt" (kısa) dijwate ne.', '"Dirêj" (uzun) ile "kurt" (kısa) zıt anlamlıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0039
('ca734a66-8f5e-5dda-8d41-9469a200f9fb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "ez dixwazim" hevoka çi demê ye?', 'Dema borî', 'Dema niha', 'Dema bê', 'Raweya fermanî', 'B', 'Pêşgira "di-" nîşana dema niha ye. "Ez dixwazim" daxwazeke niha nîşan dide, ne ya borî ne ya pêşerojê.', 'Pêşgira "di-" nîşana dema niha ye. "Ez dixwazim" daxwazeke niha nîşan dide, ne ya borî ne ya pêşerojê.', '"di-" ön eki şimdiki zamanı gösterir. "Ez dixwazim" cümlesi süren bir isteği anlatır, geçmişi ya da geleceği değil.', 3, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0040
('d7fd2975-cbd2-5389-90bf-e7b520e69ec7', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de paşgira "-van" di peyvên wek "dergehvan" de çi diyar dike?', 'Kesê ku karekî dike', 'cînavkên tewandî', 'rênivîsa Hawarê', 'Zayend: "-ê" nêr, "-a" mê', 'A', '"-van" paşgira kirdeyê ye: dergehvan (kapıcı), stranvan, hunervan.', '"-van" paşgira kirdeyê ye: dergehvan (kapıcı), stranvan, hunervan.', '"-van" fail ekidir: dergehvan (kapıcı), stranvan, hunervan.', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0041
('812e6705-154a-5c8e-bc44-3a44c6cc0f25', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "were" û "biçe" kîjan raweyê nîşan didin?', 'Raweya bilanî', 'Raweya fermanî', 'Dema borî', 'Dema bê', 'B', 'Herdu jî ferman in: "were" (gel), "biçe" (git).', 'Herdu jî ferman in: "were" (gel), "biçe" (git).', 'İkisi de emirdir: "were" (gel), "biçe" (git).', 4, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0042
('b4214c94-8110-506e-9b65-a73b2e52b386', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de "min got" û "ez gotim" — kîjan rast e?', '"Ez gotim" rast e', 'Herdu jî rast in', 'Herdu jî şaş in', '"Min got" rast e', 'D', 'Lêkera "gotin" gerguhêz e; di dema borî de biker tê tewandin: "min got".', 'Lêkera "gotin" gerguhêz e; di dema borî de biker tê tewandin: "min got".', '"Gotin" geçişlidir; geçmiş zamanda özne büküme girer: "min got".', 5, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0043
('b6c45301-9022-5bae-ab91-11a0c5f75db5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de cudahiya "-ê" û "-a" ya veqetandekê çi ye?', 'Hejmar: "-ê" yekjimar, "-a" pirjimar', 'Zayend: "-ê" nêr, "-a" mê', 'Dem: "-ê" borî, "-a" niha', 'Rewş: "-ê" xwerû, "-a" tewandî', 'B', '"Bavê min" (nêr) lê "diya min" (mê) — veqetandek zayendê nîşan dide.', '"Bavê min" (nêr) lê "diya min" (mê) — veqetandek zayendê nîşan dide.', '"Bavê min" (eril) ama "diya min" (dişil) — izafe cinsiyeti gösterir.', 5, true, 'multiple_choice', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0044
('e65ee172-0dde-5a58-bfc8-5c39942ee503', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "hevîr" bi Tirkî çi ye?', 'hamur', 'peynir', 'tuz', 'yağ', 'A', '"Hevîr" bi Tirkî "hamur" e; têkeliya ard û avê ye ku nan jê tê çêkirin. Mînak: "Dayik hevîr dike."', '"Hevîr" bi Tirkî "hamur" e; têkeliya ard û avê ye ku nan jê tê çêkirin. Mînak: "Dayik hevîr dike."', '"Hevîr" Türkçede "hamur" demektir; ekmek yapılan un ve su karışımıdır. Örnek: "Dayik hevîr dike." (Anne hamur yoğuruyor.)', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0045
('9c2181d3-3686-5308-85b2-72c9d8ae4a3b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hevwateya peyva "westiyayî" di Kurmancî de kîjan e?', 'Kêfxweş', 'Betilî', 'Bilez', 'Nexweş', 'B', '"Westiyayî" û "betilî" herdu jî wateya bêhalbûnê didin.', '"Westiyayî" û "betilî" herdu jî wateya bêhalbûnê didin.', '"Westiyayî" ve "betilî" ikisi de yorgunluk anlamındadır.', 3, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0046
('a686b1e1-bafc-55e2-998b-0000a3986688', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Rast e an şaş e: Di Kurmancî de sifet (rengdêr) piştî navdêrê tê.', 'Rast', 'Şaş', '-', '-', 'A', 'Wek "mala mezin" — rengdêr piştî navdêrê tê û bi veqetandekê tê girêdan.', 'Wek "mala mezin" — rengdêr piştî navdêrê tê û bi veqetandekê tê girêdan.', '"Mala mezin" gibi — sıfat isimden sonra gelir ve izafeyle bağlanır.', 4, true, 'true_false', NULL, NULL, 'Rêzimana kurdî — Bedirxan & Lescot', 'Celadet Alî Bedirxan & Roger Lescot, Grammaire Kurde (Dialecte Kurmandji), Paris 1970; Hawar (1932-1943)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0047
('d2f02fae-d317-5405-9365-cce62236edeb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "zanîngeh" ji kîjan beşan pêk tê?', 'Zan + îng', 'Za + nîngeh', 'Zanîn + geh (cih)', 'Zanî + gehîn', 'C', '"Geh" paşgira cih e: cihê zanînê.', '"Geh" paşgira cih e: cihê zanînê.', '"Geh" yer ekidir: bilgi yeri, üniversite.', 3, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_ziman_0049
('4170a7bf-a530-58c1-890a-5f7df810ecbd', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Li gorî rastnivîsa kurmancî, amûra ku pê goşt û nan tên birîn ("bıçak") çawa tê nivîsîn?', 'kar', 'ker', 'kêr', 'kir', 'C', '"Kêr" bi "ê"ya dirêj tê nivîsîn; heke bi "e"ya kurt were nivîsîn, dibe "ker", ango heywanê barkêş. Ji ber vê yekê cudahiya "e" û "ê" wateyê diguherîne.', '"Kêr" bi "ê"ya dirêj tê nivîsîn; heke bi "e"ya kurt were nivîsîn, dibe "ker", ango heywanê barkêş. Ji ber vê yekê cudahiya "e" û "ê" wateyê diguherîne.', '"Kêr" uzun "ê" ile yazılır; kısa "e" ile yazılırsa "ker", yani eşek olur. Bu yüzden "e" ile "ê" arasındaki fark anlamı değiştirir.', 1, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'Kürtçe Dersler-1 - (Kürtçe Alfabesi - Alfabeya Kurdî) | Bernamegeh', 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_001
('867055e4-a03a-548d-b764-802161056670', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di rastnivîsa kurmancî de dengekî taybet (pevdeng) heye ku bi du tîpan tê nivîsîn. Ev herdu tîp kîjan in?', 'kw', 'qw', 'hw', 'xw', 'D', 'Ev deng di peyvên wek "xwendin" û "xweş" de heye. Hin herêm tenê "x" dibêjin, lê di rastnivîsa kurmancî de divê "xw" were nivîsîn.', 'Ev deng di peyvên wek "xwendin" û "xweş" de heye. Hin herêm tenê "x" dibêjin, lê di rastnivîsa kurmancî de divê "xw" were nivîsîn.', 'Bu ses "xwendin" (okumak) ve "xweş" (güzel) gibi sözcüklerde bulunur. Bazı yörelerde yalnızca "x" söylense de Kurmancî yazımında "xw" yazılmalıdır.', 1, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'Alfabeya kurdî ya latînî - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_002
('20c5edaa-c6a4-5a65-ba1c-c37e89a2206a', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Li gorî rastnivîsa kurmancî, peyva ku piştî nîşaneya xalê (.) tê, bi çi dest pê dike?', 'Bi jimareyeke rêzîn', 'Bi tîpa girdek (mezin)', 'Bi tîpa hûrdek (piçûk)', 'Bi nîşaneya bêhnokê', 'B', 'Xal dawiya hevokê nîşan dide. Hevoka nû bi tîpa girdek dest pê dike.', 'Xal dawiya hevokê nîşan dide. Hevoka nû bi tîpa girdek dest pê dike.', 'Nokta cümlenin bittiğini gösterir. Yeni cümle büyük harfle başlar.', 1, true, 'multiple_choice', NULL, 'https://zimannas.wordpress.com/2016/04/03/xalbendi-di-nivisina-kurdi-de/', 'XALBENDÎ di nivîsîna kurdî de – Zimannas (Mehmet Özer, Kovara Kanîzar 5)', 'https://zimannas.wordpress.com/2016/04/03/xalbendi-di-nivisina-kurdi-de/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_003
('5bccec3f-39ac-5a11-8fc8-9011129d8998', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan tîp di alfabeya kurmancî de heye, lê di alfabeya tirkî de tune ye?', 'Ü', 'Ö', 'Ğ', 'X', 'D', '"X" dengekî qirikê yê hişk nîşan dide, wek "x"ya di "xwarin" û "xêr" de. Tîpên "ö", "ü" û "ğ" yên tirkî di alfabeya kurmancî ya 31 tîpî de nînin.', '"X" dengekî qirikê yê hişk nîşan dide, wek "x"ya di "xwarin" û "xêr" de. Tîpên "ö", "ü" û "ğ" yên tirkî di alfabeya kurmancî ya 31 tîpî de nînin.', '"X" gırtlaktan çıkan sert bir sesi gösterir; "xwarin" (yemek) ve "xêr" (hayır) sözcüklerindeki gibi. Türkçedeki "ö", "ü" ve "ğ" ise 31 harfli Kurmancî alfabesinde yoktur.', 1, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'Kürtçe Dersler-1 - (Kürtçe Alfabesi - Alfabeya Kurdî) | Bernamegeh', 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_004
('fa04f9a6-44db-5226-9675-fb77b20438f5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di alfabeya kurmancî de kîjan sê tîp dengdêrên kurt in?', 'a, ê, o', 'a, o, û', 'e, i, u', 'ê, î, û', 'C', 'Ji heşt dengdêran sê kurt in (e, i, u) û pênc dirêj in (a, ê, î, o, û). Loma "i" û "î" an "u" û "û" tîpên cuda ne.', 'Ji heşt dengdêran sê kurt in (e, i, u) û pênc dirêj in (a, ê, î, o, û). Loma "i" û "î" an "u" û "û" tîpên cuda ne.', 'Sekiz ünlüden üçü kısa (e, i, u), beşi uzundur (a, ê, î, o, û). Bu yüzden "i" ile "î" ya da "u" ile "û" ayrı harflerdir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_alphabets', 'Kurdish alphabets - Wikipedia', 'https://en.wikipedia.org/wiki/Kurdish_alphabets', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_005
('543fbb6e-17c5-5ca2-8fdb-71927fd19754', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Dengê tîpa kurmancî "i" (bê kumik) di alfabeya tirkî de bi kîjan tîpê tê nîşandan?', 'u', 'i', 'ü', 'ı', 'D', '"i"ya kurmancî dengdêreke kurt e û wek "ı"ya tirkî tê xwendin, mînak "bi" wek "bı". "î"ya bi kumik jî wek "i"ya tirkî ye.', '"i"ya kurmancî dengdêreke kurt e û wek "ı"ya tirkî tê xwendin, mînak "bi" wek "bı". "î"ya bi kumik jî wek "i"ya tirkî ye.', 'Kurmancîdeki "i" kısa bir ünlüdür ve Türkçedeki "ı" gibi okunur; örneğin "bi", "bı" diye okunur. Şapkalı "î" ise Türkçedeki "i" gibidir.', 2, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'Kürtçe Dersler-1 - (Kürtçe Alfabesi - Alfabeya Kurdî) | Bernamegeh', 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_006
('4d162fa5-80ef-56eb-a171-aefee86b33d5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di xalbendiya kurmancî de navê nîşaneya "?" çi ye?', 'baneşan', 'pirsnîşan', 'xalebêhnok', 'xalecot', 'B', '"Pirsnîşan" di dawiya hevokên pirsiyarî de tê danîn. "Baneşan" (!), "xalebêhnok" (;) û "xalecot" (:) nîşaneyên din ên xalbendiyê ne.', '"Pirsnîşan" di dawiya hevokên pirsiyarî de tê danîn. "Baneşan" (!), "xalebêhnok" (;) û "xalecot" (:) nîşaneyên din ên xalbendiyê ne.', '"Pirsnîşan" soru cümlelerinin sonuna konur. "Baneşan" (!), "xalebêhnok" (;) ve "xalecot" (:) diğer noktalama işaretleridir.', 2, true, 'multiple_choice', NULL, 'https://zimannas.wordpress.com/2016/04/03/xalbendi-di-nivisina-kurdi-de/', 'XALBENDÎ di nivîsîna kurdî de – Zimannas (Mehmet Özer, Kovara Kanîzar 5)', 'https://zimannas.wordpress.com/2016/04/03/xalbendi-di-nivisina-kurdi-de/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_007
('92252e10-c6d0-58f2-9855-1d23ad07b37c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di alfabeya kurmancî de kîjan sê tîp bi kumikê (^) tên nivîsîn?', 'ç, ş, û', 'â, ô, û', 'a, o, u', 'ê, î, û', 'D', '"ê", "î" û "û" dengdêrên dirêj in û bi kumikê tên nivîsîn. "ç" û "ş" jî tîpên bi çengel in, ne bi kumik.', '"ê", "î" û "û" dengdêrên dirêj in û bi kumikê tên nivîsîn. "ç" û "ş" jî tîpên bi çengel in, ne bi kumik.', '"ê", "î" ve "û" uzun ünlülerdir ve şapkayla yazılır. "ç" ile "ş" ise şapkalı değil, çengelli harflerdir.', 2, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'Kürtçe Dersler-1 - (Kürtçe Alfabesi - Alfabeya Kurdî) | Bernamegeh', 'https://www.bernamegeh.org/kurtce-dersler-1-kurtce-alfabesi-alfabeya-kurdi/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_008
('135d314e-b5b0-5eac-813a-f78b167e3da7', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji kîteyên ku bi dengdarekê diqedin, wek "av" û "dar", re çi tê gotin?', 'kîteyên kurt', 'kîteyên vekirî', 'kîteyên girtî', 'kîteyên dirêj', 'C', 'Kîteya ku bi dengdarekê diqede girtî ye (ax, av, dar); ya ku bi dengdêrekê diqede vekirî ye (ba, za, da).', 'Kîteya ku bi dengdarekê diqede girtî ye (ax, av, dar); ya ku bi dengdêrekê diqede vekirî ye (ba, za, da).', 'Ünsüzle biten hece kapalıdır (ax, av, dar); ünlüyle biten hece ise açıktır (ba, za, da).', 3, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/K%C3%AEte', 'Kîte - Wîkîpediya', 'https://ku.wikipedia.org/wiki/K%C3%AEte', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_009
('2a9ec6c5-3242-5fab-a7b8-f0bf90a1de16', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Celadet Bedirxan alfabeya kurdî ya latînî cara pêşîn di 15ê kîjan mehê de, di hejmara yekem a Hawarê (1932) de, belav kir?', 'Hezîran', 'Adar', 'Nîsan', 'Gulan', 'D', 'Hejmara yekem a Hawarê di 15ê gulana 1932an de derket û alfabe bi wê belav bû. Ji ber vê yekê 15ê gulanê îro wek Roja Zimanê Kurdî tê pîrozkirin.', 'Hejmara yekem a Hawarê di 15ê gulana 1932an de derket û alfabe bi wê belav bû. Ji ber vê yekê 15ê gulanê îro wek Roja Zimanê Kurdî tê pîrozkirin.', 'Hawar''ın ilk sayısı 15 Mayıs 1932''de çıktı ve alfabe onunla yayıldı. Bu yüzden 15 Mayıs bugün Kürt Dili Günü olarak kutlanır.', 3, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'Alfabeya kurdî ya latînî - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_010
('88328d8a-10dd-55f2-901d-067307af91ec', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hejmarên pêşîn ên Hawarê de, heta hejmara 24an, cihê kîjan du tîpan li gorî îro berevajî bû?', 'q û k', 'w û v', 'c û ç', 'x û h', 'A', 'Berî hejmara 24an "kovara kurdî" wek "qovara qurdî" dihate nivîsîn. Paşê cihê "q" û "k" hat rastkirin û forma îroyîn cih girt.', 'Berî hejmara 24an "kovara kurdî" wek "qovara qurdî" dihate nivîsîn. Paşê cihê "q" û "k" hat rastkirin û forma îroyîn cih girt.', '24. sayıdan önce "kovara kurdî" ifadesi "qovara qurdî" diye yazılıyordu. Sonra "q" ile "k"nin yeri düzeltildi ve bugünkü biçim yerleşti.', 4, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'Alfabeya kurdî ya latînî - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_011
('5511074c-dd5b-5564-8528-68096458d58c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Berî alfabeya Hawarê, yekem alfabeya kurdî ya bi tîpên latînî di sala 1928an de li Ermenistanê ji aliyê Erebê Şemo û kê ve hat amadekirin?', 'Tewfîq Wehbî', 'Qanatê Kurdo', 'Îsahak Marogûlov', 'Kamuran Bedirxan', 'C', 'Îsahak Marogûlov zimannas bû; wî bi Erebê Şemo re alfabeya kurdî ya latînî amade kir.', 'Îsahak Marogûlov zimannas bû; wî bi Erebê Şemo re alfabeya kurdî ya latînî amade kir.', 'İsahak Marogulov bir dilbilimciydi; Erebê Şemo ile birlikte Latin harfli Kürt alfabesini hazırladı.', 4, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'Alfabeya kurdî ya latînî - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Alfabeya_kurd%C3%AE_ya_lat%C3%AEn%C3%AE', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_012
('870d9956-99cb-572a-8a36-188152627719', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Celadet Bedirxan di Hawarê de pêşniyar kir ku ji bo dengên erebî yên ح û غ, li ser tîpên "h" û "x" kîjan nîşan were danîn?', 'du xal (¨)', 'tîlde (~)', 'kumik (^)', 'çengel (¸)', 'A', 'Bi vê pêşniyarê "ḧ" û "ẍ" derketin. Ev ne tîpên serbixwe yên alfabeyê ne; bi piranî ji bo cudakirina peyvên ji erebî hatine tên bikaranîn.', 'Bi vê pêşniyarê "ḧ" û "ẍ" derketin. Ev ne tîpên serbixwe yên alfabeyê ne; bi piranî ji bo cudakirina peyvên ji erebî hatine tên bikaranîn.', 'Bu öneriyle "ḧ" ve "ẍ" ortaya çıktı. Bunlar alfabenin bağımsız harfleri sayılmaz; çoğunlukla Arapçadan gelen sözcükleri ayırt etmek için kullanılır.', 5, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Alfabey%C3%AAn_kurd%C3%AE', 'Alfabeyên kurdî - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Alfabey%C3%AAn_kurd%C3%AE', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_rastnivisin_013
