('b911c727-6300-5ff2-8979-2fb6da242762', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "destpêk" bi Tirkî çi ye?', 'Ben iyiyim', 'Başlangıç', 'Dokuz', 'Nasılsın?', 'B', '"destpêk" = "başlangıç". Mînak: Destpêka çîrokê pir xweş bû.', '"destpêk" = "başlangıç". Mînak: Destpêka çîrokê pir xweş bû.', '"destpêk" = "başlangıç". Örnek: Hikâyenin başlangıcı çok güzeldi.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_0121
('922fedc7-a4a1-5683-b300-0be34a0520e0', (select id from categories where name = 'Ziman'), 'ku-kmr', '"Mal" û "xanî" herdu jî bi tirkî wateya "ev"ê didin.', 'Rast', 'Şaş', '-', '-', 'A', 'Peyva "mal" ji bo malbatê, "xanî" jî ji bo avahiyê tê bikaranîn; herdu jî bi tirkî wateya "ev"ê didin.', 'Peyva "mal" ji bo malbatê, "xanî" jî ji bo avahiyê tê bikaranîn; herdu jî bi tirkî wateya "ev"ê didin.', NULL, 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2049
('ccabeb26-ed71-5faf-b84f-f9a017679fed', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kurmancî û Soranî wek du zaravayên girîng ên çi têne zanîn?', 'Kurdî', 'Rûsî', 'Erebî', 'Yewnanî', 'A', 'Kurmancî û soranî du zaravayên sereke yên herî belav ên kurdî ne.', 'Kurmancî û soranî du zaravayên sereke yên herî belav ên kurdî ne.', 'Kurmancî ve Soranî, Kürtçe denildiğinde en yaygın iki ana lehçe/standart olarak öne çıkar.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2231
('bb794088-8013-57f6-a32e-e1d5c6a451e6', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kurmancî bi piranî bi kîjan pergala nivîsandinê tê nivîsandin?', 'Alfabeya kurdî ya bingeh-erebî', 'Nivîsa mîxî', 'Alfabeya Hawarê ya bingeh-latînî', 'Pergala kanayê ya Japonî', 'C', 'Kurmancî bi taybetî li Tirkiye û Sûriyeyê bi alfabeya Hawarê ya latînî belav bûye.', 'Kurmancî bi taybetî li Tirkiye û Sûriyeyê bi alfabeya Hawarê ya latînî belav bûye.', 'Kurmancî, özellikle Türkiye ve Suriye bağlamında Latin temelli Hawar alfabesiyle yaygınlaşmıştır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2232
('d4458fd0-00e1-574c-b0e0-eb6af3f68174', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Soranî li Iraq û Îranê bi piranî bi kîjan pergala nivîsê tê nivîsandin?', 'Alfabeya Hawarê ya bingeh-latînî', 'Alfabeya kurdî ya bingeh-erebî', 'Nivîsa rûnîk', 'Alfabeya Gurcî', 'B', 'Soranî li Iraq û Îranê bi alfabeya kurdî ya bi bingeha erebî tê nivîsandin.', 'Soranî li Iraq û Îranê bi alfabeya kurdî ya bi bingeha erebî tê nivîsandin.', 'Soranî, Irak ve İran’da Arap temelli Kürt alfabesiyle yaygın biçimde yazılır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2233
('a80f5d58-ff8b-54e7-bc59-e138870df947', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurdî de peyva "heval" bi giştî tê wateya çi?', 'Spas', 'Bira', 'Dost', 'Dema bê', 'C', 'Heval di zimanê rojane de dost e; di çarçoveya siyasî-komî de wateya hevrêtiyê digire.', 'Heval di zimanê rojane de dost e; di çarçoveya siyasî-komî de wateya hevrêtiyê digire.', 'Heval, gündelik kullanımda arkadaş; siyasal-kolektif bağlamda yoldaş anlamında kullanılır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2237
('f24a54ca-36fd-5d91-8eec-bdbf9dd44950', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di xebatên naskirina axaftina kurdî de projeya Jira di kîjan qadê de wek mînak tê nîşandan?', 'Korpusa dengî û pergala tîpguhêzî ya Kurmancî', 'Korpusa dengî û pergala naskirinê ya Kurdiya Navîn', 'Korpusa nivîskî û pergala wergerê ya Zazakî', 'Korpusa dengî û pergala sentezê ya Hewramî', 'B', 'Jira ji bo kurdiya navîn wek korpusa axaftinê û xebateke naskirina dengî ya bi ferhengeke mezin hatiye pêşkêşkirin.', 'Jira ji bo kurdiya navîn wek korpusa axaftinê û xebateke naskirina dengî ya bi ferhengeke mezin hatiye pêşkêşkirin.', 'Jira, Merkezî Kürtçe için konuşma korpusu ve büyük sözvarlıklı konuşma tanıma çalışması olarak sunulmuştur.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2241
('c19c0e55-1ef6-50da-b2fc-08a07ad0c0f4', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di Kurmancî de peyva "mast" kîjan xwarinê nîşan dide?', 'Madeya şîrîn a ku hingiv çêdikin', 'Xwarina hişk a ku ji şîr tê çêkirin', 'Rûnê ku ji şîr tê derxistin', 'Xwarina şîrî ya bi tirşandinê tê çêkirin', 'D', '"mast" = "yoğurt". Mînak: Ji mast dew çêdibe.', '"mast" = "yoğurt". Mînak: Ji mast dew çêdibe.', '"mast" = "yoğurt". Örnek: Yoğurttan ayran yapılır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2599
('f8d75cb2-0cb0-5b4d-9ce1-ec4254728886', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "çûn" bi Tirkî çi ye?', 'Gitmek', 'Gelmek', 'Yemek', 'Görmek', 'A', '"çûn" = "gitmek". Mînak: Ez diçim malê.', '"çûn" = "gitmek". Mînak: Ez diçim malê.', '"çûn" = "gitmek". Örnek: Eve gidiyorum.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2625
