('38fbf109-6c46-570f-83ed-9e1125dc2beb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Cînavkên wekî "min, te, wî, wê, me, we, wan" yên ketine bin tewandinê çi ne?', 'ergatîf', 'ezafe', 'cînavkên tewandî', 'daçekên hevedudanî', 'C', '"cînavkên tewandî" tê vê wateyê: cînavkên wekî "min, te, wî, wê, me, we, wan" ku di bin tewandinê de ne.', '"cînavkên tewandî" tê vê wateyê: cînavkên wekî "min, te, wî, wê, me, we, wan" ku di bin tewandinê de ne.', '"cînavkên tewandî" şu anlama gelir: büküm (tewandin) almış "min, te, wî, wê, me, we, wan" gibi zamirler.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20076
('f6903fb3-b4e2-5186-95d9-e4be4db4e8b0', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Daçekên hevedudanî çi ne?', 'guhertina paşgira navdêr an cînavkan li gorî rola wan a di hevokê de', 'avahiya lêkerê ya ku kiryarek berî kiryareke din a rabirdûyê qediyaye nîşan dide', 'peyvên wekî "di... de, bi... re, ji... re" ku têkiliyên cih nîşan didin', 'pergala alfabeya kurdî ya bi tîpên latînî ku ji aliyê Celadet Bedirxan ve hatibû amadekirin', 'C', '"daçekên hevedudanî" tê vê wateyê: peyvên wekî "di... de, bi... re, ji... re" ku têkiliyên cih nîşan didin.', '"daçekên hevedudanî" tê vê wateyê: peyvên wekî "di... de, bi... re, ji... re" ku têkiliyên cih nîşan didin.', '"daçekên hevedudanî" şu anlama gelir: yer ilişkilerini gösteren "di... de, bi... re, ji... re" gibi sözcükler.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20100
('2b5cf310-88bb-5a54-a88b-d65c756d14bd', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Lêkerên ku ji bo temamkirina wateyê pêdiviya wan bi bireserê heye çi ne?', 'ergatîf', 'rênivîsa Hawarê', 'lêkera gerguhêz', 'tewandin', 'C', '"lêkera gerguhêz" tê vê wateyê: lêkerên ku hewcedariya wan bi bireserê tewandî heye bo temamkirina wateyê.', '"lêkera gerguhêz" tê vê wateyê: lêkerên ku hewcedariya wan bi bireserê tewandî heye bo temamkirina wateyê.', '"lêkera gerguhêz" şu anlama gelir: anlamını tamamlamak için bükümlü nesneye ihtiyaç duyan fiiller.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20126
('b3d2fac6-10e1-5df6-8cd6-7bcf72f3ac9c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Pergala alfabeya kurdî ya bi tîpên latînî ku Celadet Bedirxan amade kiriye çi ye?', 'lêkera gerguhêz', 'daçekên hevedudanî', 'cînavkên kesane', 'rênivîsa Hawarê', 'D', '"rênivîsa Hawarê" tê vê wateyê: pergala alfabeya kurdî ya bi tîpên latînî ku ji aliyê Celadet Bedirxan ve hatibû amadekirin.', '"rênivîsa Hawarê" tê vê wateyê: pergala alfabeya kurdî ya bi tîpên latînî ku ji aliyê Celadet Bedirxan ve hatibû amadekirin.', '"rênivîsa Hawarê" şu anlama gelir: Celadet Bedirxan''ın hazırladığı Latin harfli Kürt alfabesi sistemi.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20151
('3a4274cb-5e1a-5101-b418-3c3ac192d9e1', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Cînavkên wekî "ez, tu, ew, em, hûn, ew" yên bo kesan tên bikaranîn çi ne?', 'lêkera gerguhêz', 'cînavkên tewandî', 'cînavkên kesane', 'paşgirên tewandinê', 'C', '"cînavkên kesane" tê vê wateyê: cînavkên wekî "ez, tu, ew, em, hûn, ew" ên ku bo kesan tên bikaranîn.', '"cînavkên kesane" tê vê wateyê: cînavkên wekî "ez, tu, ew, em, hûn, ew" ên ku bo kesan tên bikaranîn.', '"cînavkên kesane" şu anlama gelir: kişiler için kullanılan "ez, tu, ew, em, hûn, ew" gibi göstericiler.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20176
('561527f4-5679-5fe3-83c2-ff90010d2b87', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Avahiya lêkerê ya ku nîşan dide kiryarek berî kiryareke din a rabirdûyê qediyaye çi ye?', 'lêkera gerguhêz', 'cînavkên kesane', 'daçekên hevedudanî', 'dema borî ya dûr', 'D', '"dema borî ya dûr" tê vê wateyê: avahiya lêkerê ya ku kiryarek berî kiryareke din a rabirdûyê qediyaye nîşan dide.', '"dema borî ya dûr" tê vê wateyê: avahiya lêkerê ya ku kiryarek berî kiryareke din a rabirdûyê qediyaye nîşan dide.', '"dema borî ya dûr" şu anlama gelir: çok uzak bir geçmişte olan eylemi gösteren fiil yapısı.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20201
('508123b7-3a59-5da3-97d5-4e5567c80bc4', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hêmanên wekî "-î, -ê, -an" yên di tewandina navdêran de cih digirin çi ne?', 'dema borî ya dûr', 'cînavkên kesane', 'paşgirên tewandinê', 'ezafe', 'C', '"paşgirên tewandinê" tê vê wateyê: hêmanên wekî "-î, -ê, -an" ku di tewandina navdêran de cih digirin.', '"paşgirên tewandinê" tê vê wateyê: hêmanên wekî "-î, -ê, -an" ku di tewandina navdêran de cih digirin.', '"paşgirên tewandinê" şu anlama gelir: adların bükümünde yer alan "-î, -ê, -an" gibi ekler.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20226
('75fd1c7a-f535-5e7a-8ada-69361890902b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "fermo" bi Tirkî çi ye?', 'Lütfen', 'Teşekkürler', 'Özür dilerim', 'Buyurun', 'D', 'Di Kurmancî de ji bo "buyurun" peyva "fermo" tê bikaranîn.', 'Di Kurmancî de ji bo "buyurun" peyva "fermo" tê bikaranîn.', 'Kurmancîde "buyurun" için "fermo" kullanılır.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_30013
('698682f9-fed9-5b6e-a46b-9052b35caca4', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Wateya "ji kerema xwe" bi Tirkî "teşekkür ederim" e?', 'Rast', 'Şaş', '-', '-', 'B', '"ji kerema xwe" tê wateya "lütfen". "Spas dikim" tê wateya "teşekkür ederim".', '"ji kerema xwe" tê wateya "lütfen". "Spas dikim" tê wateya "teşekkür ederim".', '"ji kerema xwe" lütfen, "Spas dikim" teşekkür ederim demektir.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_30014
('4f4ac069-ec05-5348-8da1-b6df40b932da', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di silavkirinê de "rojbaş" bi Tirkî tê wateya "günaydın / iyi günler"?', 'Rast', 'Şaş', '-', '-', 'A', '"Rojbaş" ji bo "günaydın" an "iyi günler" tê bikaranîn.', '"Rojbaş" ji bo "günaydın" an "iyi günler" tê bikaranîn.', '"Rojbaş" günaydın ya da iyi günler için kullanılır.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_30016
('7780f84a-303e-5dd7-86b0-95ffbf223aac', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Dema êvar dibe, kesek silavê dide te; tu jî bi heman peyva silavê bersivê didî. Ev peyv çi ye?', 'Êvarbaş', 'Spas, ez baş im', 'Rojbaş', 'Şevbaş', 'A', 'Dema kesek dibêje "êvarbaş", em bi heman şêweyî dibêjin "êvarbaş".', 'Dema kesek dibêje "êvarbaş", em bi heman şêweyî dibêjin "êvarbaş".', 'Biri "êvarbaş" dediğinde aynı şekilde "êvarbaş" diye karşılık verilir.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_30017
('87e55bea-05f0-504c-b4b3-55c85274e3d3', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan peyva Kurmancî tê wateya peyva "kar" a Tirkî ya ku ji ezman dibare?', 'Baran', 'Berf', 'Ba', 'Ewr', 'B', 'Berf ava cemidî ya spî ye ku ji ezman dibare; baran av e, ba hewaya dilebite ye, ewr jî komika dilopan li ezman e.', 'Berf ava cemidî ya spî ye ku ji ezman dibare; baran av e, ba hewaya dilebite ye, ewr jî komika dilopan li ezman e.', 'Berf gökten yağan beyaz donmuş sudur; baran su olarak yağar, ba esen havadır, ewr gökteki damla topluluğudur.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=09f12b52b440b17f', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0001
('4e698284-7230-5847-b70c-3c3492462afd', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Navdêra "mal" mê ye. Ji bo wateya "evim" kîjan form rast e?', 'malê min', 'mala min', 'malên min', 'malek min', 'B', 'Di kurmancî de nîşana îzafeyê ya navdêrên mê yên yekjimar -a ye, ji ber vê yekê tê gotin "mala min". -ê ji bo nêrê yekjimar e, -ên jî ji bo pirjimar e; "malek" jî forma nediyar a yekjimar e.', 'Di kurmancî de nîşana îzafeyê ya navdêrên mê yên yekjimar -a ye, ji ber vê yekê tê gotin "mala min". -ê ji bo nêrê yekjimar e, -ên jî ji bo pirjimar e; "malek" jî forma nediyar a yekjimar e.', 'Kurmancîde izafe eki tekil dişil adlarda -a olur, bu yüzden "mala min" denir. -ê eril tekile, -ên çoğula aittir; "malek" ise belirsiz tekildir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=d444b33565bb1421', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0003
('e49a3ae2-7af6-5b95-8b59-4f94c58c2db7', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Cînavka "hûn" bi tirkî çi ye?', 'Biz', 'Onlar', 'Siz', 'Sen', 'C', 'Hûn cînavka kesê duyem ê pirjimar e û wateya wê "siz" e. Em ji bo peyva "biz", ew ji bo "onlar", tu jî ji bo "sen" tê bikaranîn; her çar jî cînavkên kesane ne.', 'Hûn cînavka kesê duyem ê pirjimar e û wateya wê "siz" e. Em ji bo peyva "biz", ew ji bo "onlar", tu jî ji bo "sen" tê bikaranîn; her çar jî cînavkên kesane ne.', 'Hûn, çoğul ikinci kişiyi yani "siz" anlamına gelir. "Biz" em, "onlar" ew, "sen" ise tudur; dördü de kişi zamiri olduğu için birlikte öğrenilir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=7a6263db28f9d1ac', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0004
('a6a5c1cc-5c94-55c7-9d26-02c43a48b8bb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di alfabeya kurmancî de bi giştî çend tîp hene?', '29', '26', '33', '31', 'D', 'Di alfabeya kurmancî ya latînî de 8 dengdêr û 23 dengdar hene, bi giştî 31 tîp. Alfabeya tirkî 29, ya îngilîzî jî 26 tîpan dihewîne.', 'Di alfabeya kurmancî ya latînî de 8 dengdêr û 23 dengdar hene, bi giştî 31 tîp. Alfabeya tirkî 29, ya îngilîzî jî 26 tîpan dihewîne.', 'Latin temelli Kurmancî alfabesinde 8 ünlü ve 23 ünsüz olmak üzere 31 harf bulunur. 29 Türk, 26 ise İngiliz alfabesinin harf sayısıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=e3c63fe13b6bb6fe', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0005
('db341440-42f2-5009-bced-69bc4cd922fb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Du peyvên cuda yên bi heman wateyê, ji hev re çi tên gotin?', 'Dijwate', 'Hevwate', 'Hevdeng', 'Peyva deynkirî', 'B', 'Peyvên hevwate cuda tên nivîsîn lê heman wateyê didin; peyvên dijwate berevajî vê yekê wateyên dijber nîşan didin.', 'Peyvên hevwate cuda tên nivîsîn lê heman wateyê didin; peyvên dijwate berevajî vê yekê wateyên dijber nîşan didin.', 'Eş anlamlı sözcükler farklı yazılır ama aynı anlamı verir; zıt anlamlılar ise karşıt anlamları gösterir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=f18a109725505f7d', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0006
('13931f17-818f-5c87-8626-3b5c8b0f7c91', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Rengê "kesk" di tirkî de kîjan reng e?', 'Yeşil', 'Sarı', 'Mavi', 'Kırmızı', 'A', 'Kesk tê wateya "yeşil"ê. Zer "sarı"yê, şîn "mavi"yê, sor jî "kırmızı"yê nîşan dide; ji ber ku her çar jî navên rengên bingehîn in, di heman kategoriyê de ne.', 'Kesk tê wateya "yeşil"ê. Zer "sarı"yê, şîn "mavi"yê, sor jî "kırmızı"yê nîşan dide; ji ber ku her çar jî navên rengên bingehîn in, di heman kategoriyê de ne.', 'Kesk yeşil demektir. Sarı zer, mavi şîn, kırmızı ise sordur; dördü de temel renk adı olduğu için aynı kavram sınıfındadır.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=1653ee18f97f081b', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0007
('1364b4a0-45b8-5fe7-914a-2fb1d852be9b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan hevok wateya "Ekmeği yedim" bi rêziman rast dide?', 'Ez nan xwar', 'Min nan xwar', 'Ez nan dixwim', 'Min nan dixwe', 'B', 'Di dema borî ya lêkerên gerguhêz de kirde vediguhere forma tewandî, ji ber vê yekê li şûna "ez", "min" tê bikaranîn. Hevoka "Ez nan dixwim" wateya xwarina nên dide.', 'Di dema borî ya lêkerên gerguhêz de kirde vediguhere forma tewandî, ji ber vê yekê li şûna "ez", "min" tê bikaranîn. Hevoka "Ez nan dixwim" wateya xwarina nên dide.', 'Geçişli fiillerin geçmiş zamanında özne bükümlü hâle girer, bu yüzden "ez" yerine "min" gelir. "Ez nan dixwim" ise ekmek yiyorum demektir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=da1ea5e56a3bef83', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0008
('35af0dfc-3654-5419-bf1f-e327c01f319d', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di malbatê de peyva "dayik" bi Tirkî kê nîşan dide?', 'Abla', 'Teyze', 'Nine', 'Anne', 'D', 'Dayik, ku bi kurtasî wek "dê" jî tê gotin, wateya peyva "anne" dide. Xaltî ji bo "teyze", dapîr jî ji bo "nine" tê bikaranîn; hemû navên merivên jin in.', 'Dayik, ku bi kurtasî wek "dê" jî tê gotin, wateya peyva "anne" dide. Xaltî ji bo "teyze", dapîr jî ji bo "nine" tê bikaranîn; hemû navên merivên jin in.', 'Dayik, kısa biçimiyle dê, anne demektir. Teyze xaltî, nine dapîr olarak geçer; hepsi kadın akraba adı olduğu için karıştırılabilir.', 1, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=26007fd35204f05c', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0009
('07316c24-7488-58b6-8269-049e8b66603a', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan form wateya "kitaplarım" bi kurmancî rast dide?', 'pirtûkên min', 'pirtûka min', 'pirtûkan min', 'pirtûkek min', 'A', 'Nîşana îzafeyê ya pirjimar -ên e. "Pirtûka min" forma yekjimar a mê ye, "pirtûkek" jî tê wateya kitêbek, lê "pirtûkan" bi tena serê xwe nikare îzafeyê ava bike.', 'Nîşana îzafeyê ya pirjimar -ên e. "Pirtûka min" forma yekjimar a mê ye, "pirtûkek" jî tê wateya kitêbek, lê "pirtûkan" bi tena serê xwe nikare îzafeyê ava bike.', 'Çoğul izafe eki -ên''dir. "Pirtûka min" tekil dişil biçimdir, "pirtûkek" bir kitap demektir, "pirtûkan" ise tek başına izafe kuramaz.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=f5e360d55efe78c3', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0010
('21aef00b-e8f9-5cb2-b7b5-8872468cac9b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hefteyekê de çend roj hene?', 'Pênc', 'Şeş', 'Heft', 'Heşt', 'C', 'Hefte heft roj in; heft hejmara piştî şeş û berî heştê ye.', 'Hefte heft roj in; heft hejmara piştî şeş û berî heştê ye.', 'Hafta yedi gündür; heft altıdan sonra ve sekizden önce gelen sayıdır.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=dd0eb3c806b3700d', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0011
('a1be445a-7181-5ca4-a58e-a9f705ed99a5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kurmancî û Soranî ji bo zimanê kurdî çi ne?', 'Du alfabe', 'Du zarava', 'Du hevok', 'Du deng', 'B', 'Her du jî du zaravayên heman zimanî ne; xezîneya peyvan a wan bi piranî hevpar e lê di deng û kişandinê de cudahî hene. Sîstema nivîsê mijarek cuda ye.', 'Her du jî du zaravayên heman zimanî ne; xezîneya peyvan a wan bi piranî hevpar e lê di deng û kişandinê de cudahî hene. Sîstema nivîsê mijarek cuda ye.', 'İkisi aynı dilin iki lehçesidir; söz varlığı büyük ölçüde ortaktır ama ses ve çekim farkları vardır. Yazı sistemi ayrı bir konudur.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=0114b3d5e11cbbbf', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0012
('f2d6078c-380f-59b4-9eb9-e10fb1a85953', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hevoka "Ez diçim" çawa tê neyînîkirin?', 'Ez neçim', 'Ez nediçim', 'Ez naçim', 'Ez biçim', 'C', 'Di kipa nîşandekê de pêşgira di- cihê xwe dide na-yê: "diçim" di neyînî de dibe "naçim". "Neçim" û "biçim" jî ên kipa daxwazê ne.', 'Di kipa nîşandekê de pêşgira di- cihê xwe dide na-yê: "diçim" di neyînî de dibe "naçim". "Neçim" û "biçim" jî ên kipa daxwazê ne.', 'Bildirme kipinde di- öneki yerini na- ekine bırakır: diçim olumsuzda naçim olur. "Neçim" ile "biçim" istek kipine aittir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=c3bc6d41b5498d39', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0013
('f590dc44-aa39-5063-a321-8c39c1e0b833', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ajalê ku bi tirkî "at" e, bi kurmancî çi ye?', 'Hesp', 'Ker', 'Ga', 'Bizin', 'A', '"Bizin" bi Tirkî "keçi" ye.', '"Bizin" bi Tirkî "keçi" ye.', 'Bizin, Türkçede "keçi" demektir.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=4fac4b938812d68c', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0014
('fdf52ff1-84cd-5099-af74-1af3d76d4d94', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "kulîlk" ji çend kîteyan pêk tê?', 'Çar', 'Yek', 'Du', 'Sê', 'C', 'Hejmara kîteyan bi hejmara dengdêran re wekhev e. Di vê peyvê de du dengdêr hene, u û î: ku-lîlk. Komkirina dengdaran hejmara kîteyan zêde nake.', 'Hejmara kîteyan bi hejmara dengdêran re wekhev e. Di vê peyvê de du dengdêr hene, u û î: ku-lîlk. Komkirina dengdaran hejmara kîteyan zêde nake.', 'Hece sayısı ünlü sayısına eşittir. Bu sözcükte u ve î olmak üzere iki ünlü vardır: ku-lîlk. Ünsüz yığını hece sayısını artırmaz.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=580f38aa96048d7b', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0015
('d2a26b45-babe-53a7-8961-86a228c34b76', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Dema ku roj diçe ava, ji wê demê re bi kurmancî çi tê gotin?', 'Sibe', 'Êvar', 'Nîvro', 'Şev', 'B', 'Êvar dema avabûna rojê ye; sibe destpêka rojê ye, nîvro nîvê rojê ye, şev jî dema tarî ya piştî rojavabûnê ye.', 'Êvar dema avabûna rojê ye; sibe destpêka rojê ye, nîvro nîvê rojê ye, şev jî dema tarî ya piştî rojavabûnê ye.', 'Êvar güneşin battığı vakittir; sibe günün başlangıcıdır, nîvro gün ortasıdır, şev batımdan sonraki karanlık zamandır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=e97d91c45500e354', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0016
('072019a6-8172-5d57-a043-ca978b48bdae', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji bo wateya "evde" kîjan bikaranîn rast e?', 'ji malê', 'bi malê', 'li malê', 'ser malê', 'C', 'Wateya cihbûnê ("-de") daçeka "li" dide. "Ji" wateya dûrbûnê ango "-den", "bi" jî wateya amûrê ango "ile" dide; "ser" bi tena serê xwe wek daçek nayê bikaranîn.', 'Wateya cihbûnê ("-de") daçeka "li" dide. "Ji" wateya dûrbûnê ango "-den", "bi" jî wateya amûrê ango "ile" dide; "ser" bi tena serê xwe wek daçek nayê bikaranîn.', 'Bulunma anlamını "li" daçeki verir. "Ji" ayrılma yani -den, "bi" araç yani ile anlamındadır; "ser" tek başına daçek olarak kullanılmaz.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=19d07dfecf159749', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0017
('186ea826-a3ed-5bce-ae96-d66c2ccf070f', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "derî" bi Tirkî çi ye?', 'Kapı', 'Pencere', 'Duvar', 'Çatı', 'A', 'Derî wateya peyva "kapı" dide. Dîwar ji bo "duvar", banî ji bo "çatı" tê gotin; peyva "pencere" di kurmancî de jî bi heman awayî tê bikaranîn. Hemû navên perçeyên malê ne.', 'Derî wateya peyva "kapı" dide. Dîwar ji bo "duvar", banî ji bo "çatı" tê gotin; peyva "pencere" di kurmancî de jî bi heman awayî tê bikaranîn. Hemû navên perçeyên malê ne.', 'Derî kapı demektir. Duvar dîwar, çatı banî olarak geçer; pencere ise Kurmancîde de aynı biçimde söylenir. Hepsi ev bölümü adıdır.', 1, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=0d444f33cb14e34d', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0018
('2f939216-7e1e-5c5a-a586-c71b132570c1', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Forma fermanî ya lêkera "xwendin" ji bo yekjimar kîjan e?', 'xwend', 'dixwîne', 'bixwîne', 'xwendiye', 'C', 'Kipa fermanî bi pêşgira bi- û koka lêkerê tê avakirin: bi + xwîn + e. "Dixwîne" tê wateya "o okuyor", "xwend" koka dema borî ye, "xwendiye" jî dema borî ya tekûz e.', 'Kipa fermanî bi pêşgira bi- û koka lêkerê tê avakirin: bi + xwîn + e. "Dixwîne" tê wateya "o okuyor", "xwend" koka dema borî ye, "xwendiye" jî dema borî ya tekûz e.', 'Emir kipi bi- öneki ve fiil köküyle kurulur: bi + xwîn + e. "Dixwîne" o okuyor, "xwend" geçmiş kök, "xwendiye" ise bitmiş geçmiştir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=be16172d03ddeb89', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0020
('c2f51cdc-1217-5929-bc32-1ee84d126cbd', (select id from categories where name = 'Ziman'), 'ku-kmr', '"yıldız" bi Kurmancî çi ye?', 'Heyv', 'Stêrk', 'Roj', 'Ewr', 'B', 'Stêrk ronahiyên biçûk ên li ezmanê şevê ne; heyv peyka mezin a şevê ye, roj stêrka ku rojê ronî dike ye, ewr jî komên dilopan ên li ezman in.', 'Stêrk ronahiyên biçûk ên li ezmanê şevê ne; heyv peyka mezin a şevê ye, roj stêrka ku rojê ronî dike ye, ewr jî komên dilopan ên li ezman in.', 'Stêrk gece göğündeki küçük ışıklardır; heyv gecenin büyük uydusudur, roj gündüzü aydınlatan yıldızdır, ewr gökteki damla kümeleridir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=eff3781fc0db50ea', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0021
('c694e86d-eaf6-5ff2-973e-7c49bca4fdcb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyveke ku ji zimanekî din hatibe girtin, jê re çi tê gotin?', 'Hevwate', 'Kîte', 'Peyva deynkirî', 'Dijwate', 'C', 'Peyva deynkirî peyva ku ji zimanekî din hatiye wergirtin e; ziman bi vî awayî ji hev peyvan digirin.', 'Peyva deynkirî peyva ku ji zimanekî din hatiye wergirtin e; ziman bi vî awayî ji hev peyvan digirin.', 'Alıntı kelime başka bir dilden alınmış sözcüktür; diller birbirinden böyle sözcükler alır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=dd6194147bd5e25b', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0022
('e17e047d-a68b-5ea4-800b-ba35d2f3204b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan navdêr di kurmancî de nêr e?', 'Nan', 'Mal', 'Roj', 'Şev', 'A', 'Ji ber ku nêr e, di îzafeyê de tê gotin "nanê germ". Mal, roj û şev mê ne: mala me, roja yekşemê, şeva sar. Zayend ji nîşana îzafeyê tê fêmkirin.', 'Ji ber ku nêr e, di îzafeyê de tê gotin "nanê germ". Mal, roj û şev mê ne: mala me, roja yekşemê, şeva sar. Zayend ji nîşana îzafeyê tê fêmkirin.', 'Eril olduğu için izafede "nanê germ" denir. Mal, roj ve şev dişildir: mala me, roja yekşemê, şeva sar. Cinsiyet izafe ekinden anlaşılır.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=f39f4e92a9cbd37e', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0023
('606ba9df-1894-5d45-a755-270704aef6a7', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hevoka "Ez ... dibînim" de ji bo "seni" kîjan cînavk rast e?', 'te', 'tu', 'ew', 'wî', 'A', 'Cînavk di rewşa bireserê de vediguhere forma tewandî: "tu" dibe "te". "Tu" kirdeya xwerû ye, "wî" kesê sêyem ê nêr e, "ew" jî kesê sêyem ê xwerû ye.', 'Cînavk di rewşa bireserê de vediguhere forma tewandî: "tu" dibe "te". "Tu" kirdeya xwerû ye, "wî" kesê sêyem ê nêr e, "ew" jî kesê sêyem ê xwerû ye.', 'Nesne konumundaki zamir bükümlü hâle girer: tu biçimi te olur. "Tu" yalın öznedir, "wî" eril üçüncü kişi, "ew" ise yalın üçüncü kişidir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=9b7e50bddf8ff259', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0025
('c3d28c22-d971-533d-ad2c-9a83a93955a0', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Rengê "reş" bi tirkî çi ye?', 'Beyaz', 'Siyah', 'Yeşil', 'Sarı', 'B', 'Reş tê wateya "siyah"ê; spî "beyaz"ê, kesk "yeşil"ê, zer jî "sarı"yê nîşan dide. Ji ber ku reş û spî li hember hev in, ev herdu bi hev re tên hînkirin.', 'Reş tê wateya "siyah"ê; spî "beyaz"ê, kesk "yeşil"ê, zer jî "sarı"yê nîşan dide. Ji ber ku reş û spî li hember hev in, ev herdu bi hev re tên hînkirin.', 'Reş siyah demektir; beyaz spî, yeşil kesk, sarı ise zerdir. Reş ile spî birbirinin karşıtı olduğu için ikisi birlikte öğretilir.', 1, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=d41797b1854b40a1', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0026
('0d8c46b3-88cc-5637-9cc1-56dcc5425e52', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kurdî di kîjan malbata zimanan de cih digire?', 'Malbata tirkî', 'Malbata samî', 'Malbata fîno-ugrî', 'Malbata hindû-ewropî', 'D', 'Kurdî ji şaxê îranî yê malbata zimanên hind-ewropî ye û bi farisî re xizm e. Erebî ji malbata samî, tirkî ji zimanên tirkî, macarî jî ji malbata fîn-ugorî ye.', 'Kurdî ji şaxê îranî yê malbata zimanên hind-ewropî ye û bi farisî re xizm e. Erebî ji malbata samî, tirkî ji zimanên tirkî, macarî jî ji malbata fîn-ugorî ye.', 'Kürtçe, Hint-Avrupa ailesinin İran kolundandır ve Farsçayla akrabadır. Arapça Sami, Türkçe Türk dilleri, Macarca ise Fin-Ugor ailesindendir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=8ebad7eaf40acbd2', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0027
('94ea4602-f267-58a6-9cb7-6f8162b296d7', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Lêkera "çûn" bi pêşgira di- ji bo kesê sêyem ê yekjimar çawa tê?', 'diçim', 'diçe', 'diçin', 'diçî', 'B', 'Nîşanên kesane bi rêzê -im, -î, -e, -in in; di kesê sêyem ê yekjimar de -e tê. "Diçim" ji bo min, "diçî" ji bo te, "diçin" jî ji bo kesên pirjimar e.', 'Nîşanên kesane bi rêzê -im, -î, -e, -in in; di kesê sêyem ê yekjimar de -e tê. "Diçim" ji bo min, "diçî" ji bo te, "diçin" jî ji bo kesên pirjimar e.', 'Kişi ekleri sırasıyla -im, -î, -e, -in biçimindedir; üçüncü tekilde -e gelir. "Diçim" ben, "diçî" sen, "diçin" ise çoğul kişiler içindir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=a2d45a1aa4782f7f', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0028
('b32c229d-5fa7-557e-83ee-eeb1e4a4e344', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva "şîr" li ser sifreyê kîjan tiştî nîşan dide?', 'Vexwarina spî ya ji heywanan tê girtin', 'Madeya şîrîn a ku mêşhingiv çêdikin', 'Xwarina ji şîr a bi tirşandinê tê çêkirin', 'Rûnê ku ji şîr tê derxistin', 'A', 'Şîr tê wateya "süt"ê. Hingiv "bal"ê, mast "yoğurt"ê, rûn jî "yağ"ê nîşan dide; ji ber ku her çar jî xwarinên taştêyê ne, vebijark nêzîkî hev in.', 'Şîr tê wateya "süt"ê. Hingiv "bal"ê, mast "yoğurt"ê, rûn jî "yağ"ê nîşan dide; ji ber ku her çar jî xwarinên taştêyê ne, vebijark nêzîkî hev in.', 'Şîr süttür. Bal hingiv, yoğurt mast, yağ ise rûn olarak geçer; dördü de süt sofrasında bulunduğu için birbirine yakın şıklardır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=ed43a6204a155288', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0029
('b2ddee46-30c5-5cf4-9b23-64e399ee9fc0', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Alfabeya kurmancî çend tîpên dengdêr dihewîne?', 'Şeş', 'Heşt', 'Deh', 'Pênc', 'B', 'Dengdêr heşt in: a, e, ê, i, î, o, u, û; 23 tîpên din jî dengdar in. Ji ber ku bêyî dengdêran kîte nayê avakirin, ev hejmar girîng e.', 'Dengdêr heşt in: a, e, ê, i, î, o, u, û; 23 tîpên din jî dengdar in. Ji ber ku bêyî dengdêran kîte nayê avakirin, ev hejmar girîng e.', 'Ünlüler a, e, ê, i, î, o, u, û olmak üzere sekizdir; geri kalan 23 harf ünsüzdür. Ünlüsüz hece kurulamadığı için bu sayı önemlidir.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=f518b8294c1df961', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0030
('a44a8d8d-49c7-5b8b-8f16-2dd7e3192d6c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Heywanê malê yê ku mişkan digire, bi kurmancî çi ye?', 'Kûçik', 'Mişk', 'Pisîk', 'Rovî', 'C', 'Pisîk heywanê malê ye ku mişkan digire û tê xwedîkirin; kûçik parêzvan e, mişk nêçîra wê ye, rovî jî heywanekî kovî ye.', 'Pisîk heywanê malê ye ku mişkan digire û tê xwedîkirin; kûçik parêzvan e, mişk nêçîra wê ye, rovî jî heywanekî kovî ye.', 'Pisîk fare yakalayan evcil hayvandır; kûçik koruyucudur, mişk onun avıdır, rovî ise yabani bir hayvandır.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=fab475a2f80bb38f', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0031
('cc455500-d86e-547e-81ca-f53e4a80663d', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji bo wateya "odanın içinde" kîjan avanî rast e?', 'di odeyê de', 'li odeyê ser', 'ji odeyê de', 'bi odeyê re', 'A', 'Di kurmancî de hin daçek du perçe ne û navdêr di navberê de digirin. Wateya hundir bi "di ... de" tê dayîn; "bi ... re" hevaltiyê, "ji" jî dûrbûnê nîşan dide.', 'Di kurmancî de hin daçek du perçe ne û navdêr di navberê de digirin. Wateya hundir bi "di ... de" tê dayîn; "bi ... re" hevaltiyê, "ji" jî dûrbûnê nîşan dide.', 'Kurmancîde bazı daçekler iki parçalıdır ve adı ortalar. İçindelik "di ... de" ile kurulur; "bi ... re" birliktelik, "ji" ise ayrılma bildirir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=89ef2cb92ebc7f42', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0032
('c6310ab3-0bf5-5ba4-8d42-230e794d6e1b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Alfabeya latînî ya kurmancî di sala 1932yan de bi kîjan kovarê belav bû?', 'Roja Nû', 'Nûbihar', 'Hawar', 'Bîrnebûn', 'C', 'Celadet Alî Bedirxan ev alfabe di kovara xwe ya ku di sala 1932an de li Şamê derxist de bikar anî; ji ber vê yekê alfabe bi navê kovarê tê zanîn. Yên din jî weşanên paşê ne.', 'Celadet Alî Bedirxan ev alfabe di kovara xwe ya ku di sala 1932an de li Şamê derxist de bikar anî; ji ber vê yekê alfabe bi navê kovarê tê zanîn. Yên din jî weşanên paşê ne.', 'Celadet Alî Bedirxan bu alfabeyi 1932''de Şam''da çıkardığı dergide kullandı; alfabe de o yüzden derginin adıyla anılır. Diğerleri sonraki yayınlardır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=a3a37ce5cc2cecd0', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0033
('eccfe61c-1378-5b4c-97f0-48bc5155c6a2', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hevoka "Ez ji ... hez dikim" de ji bo wateya "çocukları" kîjan form tê?', 'zarok', 'zarokan', 'zarokek', 'zarokên', 'B', 'Piştî daçekê navdêr vediguhere forma tewandî û nîşana tewangê ya pirjimar -an e. "Zarokên" forma îzafeyê ye, li pey xwe pêdiviya wê bi rengdêrek an xwediyekî heye.', 'Piştî daçekê navdêr vediguhere forma tewandî û nîşana tewangê ya pirjimar -an e. "Zarokên" forma îzafeyê ye, li pey xwe pêdiviya wê bi rengdêrek an xwediyekî heye.', 'Daçekten sonra ad bükümlü hâle girer ve çoğulun bükümlü eki -an''dır. "Zarokên" izafe biçimidir, ardından bir niteleyici ya da sahip ister.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=42975251d9395c8d', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0034
('2820f5d5-a761-5dc9-9597-bf36a2fff81a', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Endamê ku pê tê dîtin, bi kurmancî çi ye?', 'Guh', 'Dev', 'Çav', 'Poz', 'C', 'Çav endamê dîtinê ye; guh ji bo bihîstinê ye, dev ji bo xwarin û axaftinê ye, poz jî ji bo bêhnê ye.', 'Çav endamê dîtinê ye; guh ji bo bihîstinê ye, dev ji bo xwarin û axaftinê ye, poz jî ji bo bêhnê ye.', 'Çav görme organıdır; guh işitmek, dev yemek ve konuşmak, poz ise koklamak içindir.', 1, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=c94d77e128f9c4c7', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0035
('9637527c-0772-5e82-8831-68806fc25f0b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di rêzimanê de peyva ku kar û tevgerê nîşan dide çi ye?', 'Lêker', 'Navdêr', 'Rengdêr', 'Cînavk', 'A', 'Lêker peyva ku kar, çêbûn an rewşê nîşan dide ye; navdêr navê hebûnê ye, rengdêr taybetmendiyê dide, cînavk jî li şûna navdêrê tê.', 'Lêker peyva ku kar, çêbûn an rewşê nîşan dide ye; navdêr navê hebûnê ye, rengdêr taybetmendiyê dide, cînavk jî li şûna navdêrê tê.', 'Fiil iş, oluş ya da durum bildiren sözcüktür; ad varlığın adıdır, sıfat özellik verir, zamir adın yerine geçer.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=fd5ac391ce7fb471', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0036
('793a560a-5073-515c-9499-0a34a25064ba', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hevoka "Ez ê biçim" kîjan demê nîşan dide?', 'Dema borî', 'Fermanî', 'Dema bê', 'Daxwazî', 'C', 'Di "Ez ê biçim" de ê nîşana dema bê ye û "biçim" bi pêşgira bi- ye; ev her du nîşan bi hev re dema bê ava dikin.', 'Di "Ez ê biçim" de ê nîşana dema bê ye û "biçim" bi pêşgira bi- ye; ev her du nîşan bi hev re dema bê ava dikin.', '"Ezê biçim" biçiminde -ê gelecek zaman eki, "biçim" ise bi- ön ekli fiildir; ikisi birlikte gelecek zamanı kurar.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=67e16d94ff2e72b6', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0037
('09d77ab4-7218-5078-a518-856d5e303f7c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva tirkî ya "pencere" ji kîjan zimanî hatiye wergirtin?', 'Ji erebî', 'Ji farisî', 'Ji fransî', 'Ji yewnanî', 'B', 'Ev peyv ji forma farisî ya peyva "pencere" tê. Peyva "kitap" ji erebî, "vapur" ji fransî, "liman" jî ji yewnanî ketiye tirkî.', 'Ev peyv ji forma farisî ya peyva "pencere" tê. Peyva "kitap" ji erebî, "vapur" ji fransî, "liman" jî ji yewnanî ketiye tirkî.', 'Bu sözcük Farsça pencere biçiminden gelir. Türkçeye Arapçadan kitap, Fransızcadan vapur, Yunancadan ise liman geçmiştir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=351872f5b71f4289', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0039
('6f8ae18c-f71e-5096-a60c-abf93b29eb42', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Amûra ku pê tê nivîsandin bi kurmancî çi ye?', 'Pirtûk', 'Kaxez', 'Qelem', 'Mase', 'C', 'Qelem tê wateya "kalem"ê. Pirtûk "kitap" e, kaxez "kâğıt" e, mase jî "masa" ye; tenê qelem amûra nivîsandinê ye.', 'Qelem tê wateya "kalem"ê. Pirtûk "kitap" e, kaxez "kâğıt" e, mase jî "masa" ye; tenê qelem amûra nivîsandinê ye.', 'Qelem kalemdir. Pirtûk kitap, kaxez kâğıt, mase ise masadır; yazma aracı olan yalnız kalemdir.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=58cd3d9789063b7a', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0040
('a8e26cb3-b385-57d5-ab57-6395798b061d', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva pirsyarî ya "kengî" li ser çi disekine?', 'Dem', 'Cih', 'Kes', 'Sedem', 'A', 'Kengî tê wateya "ne zaman" û pirsa demê dike. "Li ku" pirsa cih, "kî" pirsa kes, "çima" jî pirsa sedemê dike; her yek li elementek cuda digere.', 'Kengî tê wateya "ne zaman" û pirsa demê dike. "Li ku" pirsa cih, "kî" pirsa kes, "çima" jî pirsa sedemê dike; her yek li elementek cuda digere.', 'Kengî "ne zaman" demektir ve zamanı sorar. Yeri "li ku", kişiyi "kî", sebebi ise "çima" sorar; her biri farklı bir öge arar.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=7309cb2c24696481', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0041
('248cc1c6-b107-54fb-8e97-262db1a93609', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji bo wateya "O kadın mektup yazdı" kîjan hevok rast e?', 'Wê name nivîsî', 'Ew name nivîsî', 'Wê nameyê dinivîse', 'Ew nameyê nivîsî', 'A', 'Di dema borî de kirdeya lêkera gerguhêz dikeve rewşa tewandî: awayê "ew" dibe "wê". Bireser di rewşa xwerû de dimîne û lêker li gorî bireserê tê kişandin.', 'Di dema borî de kirdeya lêkera gerguhêz dikeve rewşa tewandî: awayê "ew" dibe "wê". Bireser di rewşa xwerû de dimîne û lêker li gorî bireserê tê kişandin.', 'Geçmiş zamanda geçişli fiilin öznesi bükümlü hâle girer: ew biçimi wê olur. Nesne yalın kalır ve fiil nesneye göre çekilir.', 5, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=7427fca497bdf6b7', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0044
('c21de47e-695f-5646-84f1-9e5ccfe4d48b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Birayê bavê mirov bi kurmancî çi ye?', 'Xal', 'Met', 'Ap', 'Bapîr', 'C', 'Ap û mam hevwate ne (amca). Xal birayê dayikê ye, met xwişka bavê ye, bapîr jî bavê bav an bavê dayikê ye; navên lêzimtiyê li gorî aliyê dayik û bav ji hev cuda dibin.', 'Ap û mam hevwate ne (amca). Xal birayê dayikê ye, met xwişka bavê ye, bapîr jî bavê bav an bavê dayikê ye; navên lêzimtiyê li gorî aliyê dayik û bav ji hev cuda dibin.', 'Ap, bazı yörelerde amca demektir. Xal dayı, met hala, bapîr ise dededir; akrabalık adları anne ve baba tarafına göre ayrılır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=cc75eeb89a6d43e2', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0045
('b520f413-1438-5754-a681-64e18515e685', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Berhevoka peyvên zimanekî bi wateyên wan re çi ye?', 'Ferheng', 'Rêziman', 'Hevok', 'Alfabe', 'A', 'Ferheng peyvan bi wateyên wan re rêz dike. Rêziman qaîdeyan rave dike, alfabe rêza tîpan e, hevok jî komeke peyvan e ku wateyeke têkûz dide.', 'Ferheng peyvan bi wateyên wan re rêz dike. Rêziman qaîdeyan rave dike, alfabe rêza tîpan e, hevok jî komeke peyvan e ku wateyeke têkûz dide.', 'Sözlük, sözcükleri anlamlarıyla sıralar. Dilbilgisi kuralları anlatır, alfabe harf dizisidir, cümle ise anlamlı söz birliğidir.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=7e820f9a4f3d7d90', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0046
('c5fb825d-a3ba-5291-839b-2317e668b5ca', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Navdêra "sêv" mê ye. Wateya "kırmızı elma" çawa tê nivîsîn?', 'sêv sor', 'sêvê sor', 'sêvên sor', 'sêva sor', 'D', 'Rengdêr li pey navdêrê bi hevalbendiya îzafeyê tê; navdêra mê ya yekjimar -a digire. Avakirina bêyî vê hevalbendiyê çênabe; -ê ji nêrê yekjimar re ye, -ên jî ji pirjimarê re ye.', 'Rengdêr li pey navdêrê bi hevalbendiya îzafeyê tê; navdêra mê ya yekjimar -a digire. Avakirina bêyî vê hevalbendiyê çênabe; -ê ji nêrê yekjimar re ye, -ên jî ji pirjimarê re ye.', 'Sıfat adı izafe ekiyle izler; dişil tekil ad -a alır. Eksiz kuruluş olmaz, -ê eril tekile, -ên ise çoğula aittir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=38802b5c4390f07e', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0047
('f23b66bc-5652-5a09-a74f-e2a44591cbcb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Roja piştî Duşemê bi kurmancî çi ye?', 'Sêşem', 'Çarşem', 'Pêncşem', 'Şemî', 'A', 'Navên rojan ji hejmaran tên: du du ye, sê sisê ye, çar çar e, pênc pênc e. Gava meriv vê rêzê zanibe, hêsan e meriv derxîne kîjan roj li pey kîjanê tê.', 'Navên rojan ji hejmaran tên: du du ye, sê sisê ye, çar çar e, pênc pênc e. Gava meriv vê rêzê zanibe, hêsan e meriv derxîne kîjan roj li pey kîjanê tê.', 'Gün adları sayılardan türer: du iki, sê üç, çar dört, pênc beş. Bu sıra bilindiğinde hangi günün hangisini izlediği kolayca çıkarılır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=f89f74765007feb9', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0048
('360472a1-6afa-5b06-a649-dd39dc9a7032', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Peyva tirkî ya "yüz" hem rû hem 100 e. Ev rewş çi ye?', 'Hevwate', 'Dijwate', 'Hevdeng', 'Peyva deynkirî', 'C', 'Peyvên ku nivîsîn û xwendina wan wek hev e lê wateya wan cuda ye, hevdeng in. Di hevwateyê de peyv cuda ye lê wate wek hev e; ev herdu têgeh cuda ne.', 'Peyvên ku nivîsîn û xwendina wan wek hev e lê wateya wan cuda ye, hevdeng in. Di hevwateyê de peyv cuda ye lê wate wek hev e; ev herdu têgeh cuda ne.', 'Yazılışı ve okunuşu aynı, anlamı farklı sözcükler eş seslidir. Eş anlamlılıkta ise sözcük farklı, anlam aynıdır; ikisi farklı kavramlardır.', 3, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=32dd251a19e3dc8b', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0049
('f2c8a7d5-1eb7-5cf3-b5f8-f2be14126897', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Li ser sifreyê "goşt" heye. Ev xwarin bi tirkî çi ye?', 'Balık', 'Ekmek', 'Çorba', 'Et', 'D', 'Goşt tê wateya "et"ê. Masî "balık", nan "ekmek", şorbe jî "çorba" ye; her çar jî navên xwarinê ne, loma di heman refa têgehî de ne.', 'Goşt tê wateya "et"ê. Masî "balık", nan "ekmek", şorbe jî "çorba" ye; her çar jî navên xwarinê ne, loma di heman refa têgehî de ne.', 'Goşt et demektir. Balık masî, ekmek nan, çorba ise şorbe olarak geçer; dördü de yemek adı olduğu için aynı kavram sınıfındadır.', 1, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=a25322942688cadb', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0050
('26aa7aec-30ee-5e09-b6d3-65762f6a87fb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Hevoka bi wateya "bana söyle" bi kurmancî çawa tê avakirin?', 'li min bêje', 'ji min re bêje', 'bi min bêje', 'di min bêje', 'B', 'Wateya arastebûnê (bo kesekî) bi daçeka du-perçeyî "ji ... re" tê dayîn. "Li" cihbûnê, "bi" amûrê, "di ... de" jî hundirbûnê nîşan dide.', 'Wateya arastebûnê (bo kesekî) bi daçeka du-perçeyî "ji ... re" tê dayîn. "Li" cihbûnê, "bi" amûrê, "di ... de" jî hundirbûnê nîşan dide.', 'Yönelme anlamı iki parçalı "ji ... re" daçekiyle verilir. "Li" bulunma, "bi" araç, "di ... de" ise içindelik bildirir.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=a98cdb4970535972', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0051
('0b18f172-419c-5350-b477-29cf272868b9', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji bo xwedîtiya nêr, wateya "onun kitabı" kîjan form e?', 'pirtûka wî', 'pirtûka wê', 'pirtûkên wî', 'pirtûka wan', 'A', 'Hevalbendiya îzafeyê li gorî zayenda navdêrê ye, lê cînavk li gorî zayenda xwedî ye. Ji ber ku "pirtûk" mê ye, -a digire; cînavka xwediyê nêr "wî" ye, yê mê "wê" ye, yê pirjimar jî "wan" e.', 'Hevalbendiya îzafeyê li gorî zayenda navdêrê ye, lê cînavk li gorî zayenda xwedî ye. Ji ber ku "pirtûk" mê ye, -a digire; cînavka xwediyê nêr "wî" ye, yê mê "wê" ye, yê pirjimar jî "wan" e.', 'İzafe eki adın cinsiyetine, zamir ise sahibin cinsiyetine bakar. Kitap dişil olduğu için -a gelir; eril sahip wî, dişil wê, çoğul ise wan olur.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=4b907cd04b6d5174', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0052
('9aa81872-15be-53f4-90f7-1666cd770e60', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Heywanê çolê yê ku bi kerî digere û dijberê pez e, çi ye?', 'Hirç', 'Rovî', 'Gur', 'Kew', 'C', 'Gur bi tirkî "kurt" e. Hirç "ayı", rovî "tilki", kew jî "keklik" e; gurê ku bi kerî digere dijminê pez e.', 'Gur bi tirkî "kurt" e. Hirç "ayı", rovî "tilki", kew jî "keklik" e; gurê ku bi kerî digere dijminê pez e.', 'Gur kurttur. Hirç ayı, rovî tilki, kew ise kekliktir; sürüyle gezip koyuna saldıran gurttur.', 2, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=bfcb23468cc66829', 'approved', 'Kurmancî', 2, now()), -- yerel: ziman_x_0054
('d13c0cf7-ed12-5ad9-b4d0-93e164733266', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hevoka "Ez dixwazim ku ez ..." de lêkera "çûn" çawa tê?', 'biçim', 'diçim', 'çûm', 'naçim', 'A', 'Hevoka alîkar a piştî lêkera xwestinê (ku daxwazê nîşan dide) bi raweya daxwazî û pêşgira bi- tê avakirin. "Diçim" dema niha ya erênî nîşan dide, "çûm" dema borî ye, "naçim" jî neyînî ye.', 'Hevoka alîkar a piştî lêkera xwestinê (ku daxwazê nîşan dide) bi raweya daxwazî û pêşgira bi- tê avakirin. "Diçim" dema niha ya erênî nîşan dide, "çûm" dema borî ye, "naçim" jî neyînî ye.', 'İstek bildiren xwestin fiilinden sonraki yan cümle bi- önekli istek kipiyle kurulur. "Diçim" bildirme, "çûm" geçmiş, "naçim" ise olumsuzdur.', 4, true, 'multiple_choice', NULL, NULL, 'Ziman û rêziman — Kurmancî', 'internal:expansion_2026_08/ziman_x#gate=validate_batch.py#hash=00c1fa82db23c0e7', 'approved', 'Kurmancî', 2, now()) -- yerel: ziman_x_0055
